using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Http;using Microsoft.AspNetCore.Mvc;using TransPort.Api.Controllers;using TransPort.Api.Modules.Construccion.DTOs;using TransPort.Api.Modules.Construccion.Repositories;
namespace TransPort.Api.Tests;
public sealed class ConstruccionesControllerTests
{[Fact]public async Task Listar_PropagaAlcance(){var r=new F();await C(r,7,"Empleado").Listar(null,null,null,default);Assert.Equal(new AlcanceConstruccion(7,false),r.A);}[Fact]public async Task Crear_RetornaId(){var r=new F{Id=22};var x=Assert.IsType<OkObjectResult>(await C(r,1,"AdministradorGeneral").Crear(new(){SedeId=1,Nombre="Puente",TipoObra="Puente",Ubicacion="Guatemala",FechaInicio=DateTime.Today,FechaFin=DateTime.Today.AddDays(1),ResponsableId=1},default));Assert.Equal(22,Assert.IsType<ResultadoConstruccionDto>(x.Value).Id);}[Fact]public async Task Obtener_Inexistente_NotFound()=>Assert.IsType<NotFoundResult>(await C(new F(),1,"AdministradorGeneral").Obtener(1,default));[Fact]public async Task Avance_PropagaAlcance(){var r=new F();Assert.IsType<OkObjectResult>(await C(r,4,"Operativo").Avance(1,new(){Porcentaje=50,Comentario="Avance"},default));Assert.Equal(new AlcanceConstruccion(4,false),r.A);}[Fact]public void ExcluyeCliente(){var a=typeof(ConstruccionesController).GetCustomAttributes(typeof(AuthorizeAttribute),true).Cast<AuthorizeAttribute>().Single();Assert.DoesNotContain("Cliente",a.Roles??"");}
private static ConstruccionesController C(IConstruccionRepository r,int id,params string[]roles){var cs=new List<Claim>{new(ClaimTypes.NameIdentifier,id.ToString())};cs.AddRange(roles.Select(x=>new Claim(ClaimTypes.Role,x)));return new(r){ControllerContext=new(){HttpContext=new DefaultHttpContext{User=new ClaimsPrincipal(new ClaimsIdentity(cs,"T"))}}};}private sealed class F:IConstruccionRepository{public long Id{get;init;}public AlcanceConstruccion?A{get;private set;}public Task<IReadOnlyList<ConstruccionListadoDto>>ListarAsync(string?e,int?s,string?b,AlcanceConstruccion a,CancellationToken ct){A=a;return Task.FromResult<IReadOnlyList<ConstruccionListadoDto>>([]);}public Task<ConstruccionDetalleDto?>ObtenerAsync(long id,AlcanceConstruccion a,CancellationToken ct)=>Task.FromResult<ConstruccionDetalleDto?>(null);public Task<ConstruccionOpcionesDto>OpcionesAsync(AlcanceConstruccion a,CancellationToken ct)=>Task.FromResult(new ConstruccionOpcionesDto([],[],[],[],[]));public Task<long>CrearAsync(CrearConstruccionRequest x,AlcanceConstruccion a,CancellationToken ct){A=a;return Task.FromResult(Id);}public Task<long>CrearActividadAsync(long id,CrearActividadConstruccionRequest x,AlcanceConstruccion a,CancellationToken ct)=>Task.FromResult(Id);public Task<long>AvanceAsync(long id,AvanceConstruccionRequest x,AlcanceConstruccion a,CancellationToken ct){A=a;return Task.FromResult(Id);}public Task<long>RecursoAsync(long id,RecursoConstruccionRequest x,AlcanceConstruccion a,CancellationToken ct)=>Task.FromResult(Id);public Task<bool>EstadoAsync(long id,string e,AlcanceConstruccion a,CancellationToken ct)=>Task.FromResult(true);public Task<bool>EliminarAsync(long id,int u,CancellationToken ct)=>Task.FromResult(true);}}
